class Component extends DCLogic {
  state = { zoomOpen: false, scale: 1, offsetX: 0, offsetY: 0, dragging: false, dragStartX: 0, dragStartY: 0, dragOffsetStartX: 0, dragOffsetStartY: 0 };

  focusClose = () => {
    const closeBtn = document.querySelector('[data-zoom-dialog="carlos-iv-1802"] [data-zoom-close]');
    if (closeBtn) { closeBtn.focus(); return; }
    requestAnimationFrame(this.focusClose);
  };
  focusTrigger = () => {
    const trigger = document.querySelector('[data-zoom-trigger="carlos-iv-1802"]');
    if (trigger) trigger.focus();
  };
  openZoom = () => {
    this.setState({ zoomOpen: true, scale: 1, offsetX: 0, offsetY: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusClose));
  };
  closeZoom = () => {
    this.setState({ zoomOpen: false });
    requestAnimationFrame(() => requestAnimationFrame(this.focusTrigger));
  };
  zoomIn = () => this.setState(s => ({ scale: Math.min(4, Math.round((s.scale + 0.5) * 10) / 10) }));
  zoomOut = () => this.setState(s => {
    const next = Math.max(1, Math.round((s.scale - 0.5) * 10) / 10);
    return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
  });
  onWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scale + delta) * 100) / 100));
      return { scale: next, offsetX: next === 1 ? 0 : s.offsetX, offsetY: next === 1 ? 0 : s.offsetY };
    });
  };
  onPointerDown = (e) => {
    if (this.state.scale <= 1) return;
    this.setState({ dragging: true, dragStartX: e.clientX, dragStartY: e.clientY, dragOffsetStartX: this.state.offsetX, dragOffsetStartY: this.state.offsetY });
  };
  onPointerMove = (e) => {
    if (!this.state.dragging) return;
    const dx = e.clientX - this.state.dragStartX;
    const dy = e.clientY - this.state.dragStartY;
    this.setState({ offsetX: this.state.dragOffsetStartX + dx, offsetY: this.state.dragOffsetStartY + dy });
  };
  onPointerUp = () => this.setState({ dragging: false });

  stopPropagation = (e) => e.stopPropagation();

  onKeyDown = (e) => {
    if (e.key === "Escape" && this.state.zoomOpen) this.closeZoom();
  };

  componentDidMount() {
    document.addEventListener("keydown", this.onKeyDown);
    if (typeof document !== "undefined" && document.documentElement) {
      document.documentElement.lang = "es";
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.onKeyDown);
  }

  renderVals() {
    const s = this.state;
    return {
      zoomOpen: s.zoomOpen,
      openZoom: this.openZoom,
      closeZoom: this.closeZoom,
      zoomInHandler: this.zoomIn,
      zoomOutHandler: this.zoomOut,
      onWheel: this.onWheel,
      onPointerDown: this.onPointerDown,
      onPointerMove: this.onPointerMove,
      onPointerUp: this.onPointerUp,
      zoomInDisabled: s.scale >= 4,
      zoomOutDisabled: s.scale <= 1,
      zoomPercent: Math.round(s.scale * 100) + "%",
      imgTransform: `translate(${s.offsetX}px, ${s.offsetY}px) scale(${s.scale})`,
      imgCursor: s.scale > 1 ? (s.dragging ? "grabbing" : "grab") : "default",
      stopPropagation: this.stopPropagation
    };
  }
}
